/* Optional icon, Unicode and text-art presentations.
   No shipped glyphs, SVG assets, fonts or runtime JavaScript. */
@layer syn.symbols {
  /* Every rule is scoped to a Syntyr root, including root-self use.
     Place on an inline SVG or a wrapper around an SVG. Keep icon artwork
     vendor-controlled: do not force stroke, fill, or stroke-width. */
  :where(.syn-root .syn-icon, .syn-root.syn-icon) {
    display: inline-block;
    inline-size: var(--syn-icon-size, 1.25em);
    block-size: var(--syn-icon-size, 1.25em);
    flex: none;
    vertical-align: -.15em;
    color: inherit;
  }
  :where(.syn-root .syn-icon > svg, .syn-root.syn-icon > svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }

  /* Opt-in icon motion. Each preset works on inline SVGs and SVG wrappers;
     no icon artwork, color, fill or stroke is modified. */
  :where(.syn-root .syn-icon:is(.syn-icon--spin, .syn-icon--pulse, .syn-icon--bounce, .syn-icon--shake, .syn-icon--wiggle, .syn-icon--pop, .syn-icon--float, .syn-icon--swing, .syn-icon--heartbeat, .syn-icon--flash, .syn-icon--ping, .syn-icon--flip, .syn-icon--nudge-left, .syn-icon--nudge-right),
         .syn-root.syn-icon:is(.syn-icon--spin, .syn-icon--pulse, .syn-icon--bounce, .syn-icon--shake, .syn-icon--wiggle, .syn-icon--pop, .syn-icon--float, .syn-icon--swing, .syn-icon--heartbeat, .syn-icon--flash, .syn-icon--ping, .syn-icon--flip, .syn-icon--nudge-left, .syn-icon--nudge-right)) {
    animation-name: var(--syn-icon-motion-keyframes);
    animation-duration: var(--syn-icon-motion-duration, 1s);
    animation-timing-function: var(--syn-icon-motion-easing, ease-in-out);
    animation-iteration-count: var(--syn-icon-motion-iterations, infinite);
    transform-origin: center;
  }
  :where(.syn-root .syn-icon--spin, .syn-root.syn-icon--spin) {
    --syn-icon-motion-keyframes: syn-icon-spin;
    animation-timing-function: var(--syn-icon-motion-easing, linear);
  }
  :where(.syn-root .syn-icon--pulse, .syn-root.syn-icon--pulse) { --syn-icon-motion-keyframes: syn-icon-pulse; }
  :where(.syn-root .syn-icon--bounce, .syn-root.syn-icon--bounce) { --syn-icon-motion-keyframes: syn-icon-bounce; }
  :where(.syn-root .syn-icon--shake, .syn-root.syn-icon--shake) { --syn-icon-motion-keyframes: syn-icon-shake; }
  :where(.syn-root .syn-icon--wiggle, .syn-root.syn-icon--wiggle) { --syn-icon-motion-keyframes: syn-icon-wiggle; }
  :where(.syn-root .syn-icon--pop, .syn-root.syn-icon--pop) { --syn-icon-motion-keyframes: syn-icon-pop; }

  :where(.syn-root .syn-icon--float, .syn-root.syn-icon--float) { --syn-icon-motion-keyframes: syn-icon-float; }
  :where(.syn-root .syn-icon--swing, .syn-root.syn-icon--swing) {
    --syn-icon-motion-keyframes: syn-icon-swing;
    transform-origin: center 10%;
  }
  :where(.syn-root .syn-icon--heartbeat, .syn-root.syn-icon--heartbeat) { --syn-icon-motion-keyframes: syn-icon-heartbeat; }
  :where(.syn-root .syn-icon--flash, .syn-root.syn-icon--flash) { --syn-icon-motion-keyframes: syn-icon-flash; }
  :where(.syn-root .syn-icon--ping, .syn-root.syn-icon--ping) { --syn-icon-motion-keyframes: syn-icon-ping; }
  :where(.syn-root .syn-icon--flip, .syn-root.syn-icon--flip) { --syn-icon-motion-keyframes: syn-icon-flip; }
  :where(.syn-root .syn-icon--nudge-left, .syn-root.syn-icon--nudge-left) { --syn-icon-motion-keyframes: syn-icon-nudge-left; }
  :where(.syn-root .syn-icon--nudge-right, .syn-root.syn-icon--nudge-right) { --syn-icon-motion-keyframes: syn-icon-nudge-right; }

  /* Run only while hovered/focused; otherwise reset to a resting pose. */
  :where(.syn-root .syn-icon--on-interact, .syn-root.syn-icon--on-interact) {
    animation-name: none;
  }
  :where(.syn-root .syn-icon--on-interact:is(:hover, :focus-visible),
         .syn-root.syn-icon--on-interact:is(:hover, :focus-visible),
         .syn-root :is(button, a, [role="button"]):not(:disabled):not([aria-disabled="true"]):is(:hover, :focus-visible) .syn-icon--on-interact,
         .syn-root:is(button, a, [role="button"]):not(:disabled):not([aria-disabled="true"]):is(:hover, :focus-visible) .syn-icon--on-interact) {
    animation-name: var(--syn-icon-motion-keyframes);
  }

  /* Disabled controls must keep nested icons still, even on direct SVG hover. */
  :where(.syn-root :is(:disabled, [aria-disabled="true"]) .syn-icon--on-interact,
         .syn-root:is(:disabled, [aria-disabled="true"]) .syn-icon--on-interact,
         .syn-root.syn-icon--on-interact:is(:disabled, [aria-disabled="true"]),
         :is(:disabled, [aria-disabled="true"]) .syn-root .syn-icon--on-interact,
         :is(:disabled, [aria-disabled="true"]) .syn-root.syn-icon--on-interact) {
    animation-name: none;
  }

  @keyframes syn-icon-spin { to { transform: rotate(360deg); } }
  @keyframes syn-icon-pulse { 50% { transform: scale(.85); opacity: .65; } }
  @keyframes syn-icon-bounce { 50% { transform: translateY(-20%); } }
  @keyframes syn-icon-shake {
    0%, 100% { transform: translateX(0); }
    20%, 60% { transform: translateX(-12%); }
    40%, 80% { transform: translateX(12%); }
  }
  @keyframes syn-icon-wiggle {
    0%, 100% { transform: rotate(0); }
    25% { transform: rotate(-13deg); }
    75% { transform: rotate(13deg); }
  }
  @keyframes syn-icon-pop { 50% { transform: scale(1.2); } }

  @keyframes syn-icon-float { 50% { transform: translateY(-12%); } }
  @keyframes syn-icon-swing {
    0%, 100% { transform: rotate(0deg); }
    25% { transform: rotate(12deg); }
    75% { transform: rotate(-12deg); }
  }
  @keyframes syn-icon-heartbeat {
    0%, 28%, 58%, 100% { transform: scale(1); }
    14% { transform: scale(1.18); }
    42% { transform: scale(1.1); }
  }
  @keyframes syn-icon-flash { 50% { opacity: .3; } }
  @keyframes syn-icon-ping {
    0%, 100% { transform: scale(1); opacity: 1; }
    60% { transform: scale(1.3); opacity: .35; }
  }
  @keyframes syn-icon-flip { 50% { transform: rotateY(180deg); } }
  @keyframes syn-icon-nudge-left { 50% { transform: translateX(-22%); } }
  @keyframes syn-icon-nudge-right { 50% { transform: translateX(22%); } }

  @media (prefers-reduced-motion: reduce) {
    :where(.syn-root .syn-icon:is(.syn-icon--spin, .syn-icon--pulse, .syn-icon--bounce, .syn-icon--shake, .syn-icon--wiggle, .syn-icon--pop, .syn-icon--float, .syn-icon--swing, .syn-icon--heartbeat, .syn-icon--flash, .syn-icon--ping, .syn-icon--flip, .syn-icon--nudge-left, .syn-icon--nudge-right),
           .syn-root.syn-icon:is(.syn-icon--spin, .syn-icon--pulse, .syn-icon--bounce, .syn-icon--shake, .syn-icon--wiggle, .syn-icon--pop, .syn-icon--float, .syn-icon--swing, .syn-icon--heartbeat, .syn-icon--flash, .syn-icon--ping, .syn-icon--flip, .syn-icon--nudge-left, .syn-icon--nudge-right)) {
      animation: none;
    }
  }

  /* Symbols belong in the DOM; CSS does not generate meaningful content. */
  :where(.syn-root .syn-symbol, .syn-root.syn-symbol) {
    display: inline-block;
    line-height: 1;
    vertical-align: -.075em;
  }
  :where(.syn-root .syn-symbol--accent, .syn-root.syn-symbol--accent) { color: var(--syn-accent, currentColor); }
  :where(.syn-root .syn-symbol--muted, .syn-root.syn-symbol--muted) { color: var(--syn-muted, currentColor); }

  /* Preserve ASCII / Unicode box geometry, with horizontal scroll instead
     of wrapping and breaking columns on a narrow screen. */
  :where(.syn-root .syn-ascii, .syn-root.syn-ascii) {
    display: block;
    max-inline-size: 100%;
    margin: 0;
    overflow-x: auto;
    white-space: pre;
    font-family: var(--syn-mono, ui-monospace, monospace);
    font-variant-ligatures: none;
    font-kerning: none;
    line-height: 1.4;
    tab-size: 4;
  }
  :where(.syn-root .syn-ascii--accent, .syn-root.syn-ascii--accent) { color: var(--syn-accent, currentColor); }
  :where(.syn-root .syn-ascii--muted, .syn-root.syn-ascii--muted) { color: var(--syn-muted, currentColor); }
}
